"use client"

import { Suspense, useEffect, useState } from "react"
import { useRouter, useSearchParams } from "next/navigation"

import {
  Conversation,
  ConversationContent,
  ConversationScrollButton,
} from "@/components/ai-elements/conversation"
import { CockpitShell } from "@/components/cockpit/cockpit-shell"
import { IncidentHeader } from "@/components/cockpit/incident-header"
import { LiveCandidatePanel } from "@/components/cockpit/live-candidate-panel"
import { PlanChecklist } from "@/components/cockpit/plan-checklist"
import { useDevinCase } from "@/hooks/use-devin-case"

export function CockpitChat() {
  return (
    <Suspense fallback={null}>
      <DevinCockpit />
    </Suspense>
  )
}

function DevinCockpit() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const caseFromUrl = searchParams.get("case")
  const devin = useDevinCase(caseFromUrl)
  const { status, launch } = devin
  const [candidatesOpen, setCandidatesOpen] = useState(true)

  useEffect(() => {
    if (caseFromUrl || status !== "idle") return
    void launch().then((caseId) => {
      if (caseId) router.replace(`/chat?case=${encodeURIComponent(caseId)}`)
    })
  }, [caseFromUrl, launch, router, status])

  async function startNewSession() {
    const caseId = await devin.launch()
    if (caseId) router.replace(`/chat?case=${encodeURIComponent(caseId)}`)
  }

  const incident = devin.snapshot?.incident ?? null
  const part = devin.snapshot?.part ?? null

  return (
    <CockpitShell
      rightSidebar={
        candidatesOpen ? (
          <LiveCandidatePanel
            candidates={devin.candidates}
            supplierRecords={devin.snapshot?.supplier_records ?? []}
            onClose={() => setCandidatesOpen(false)}
          />
        ) : undefined
      }
    >
      <div className="grid h-full min-h-0 min-w-0 grid-rows-[auto_minmax(0,1fr)] overflow-hidden">
        <IncidentHeader
          caseId={devin.caseId}
          incident={incident}
          part={part}
          sessionUrl={devin.session?.session_url ?? null}
          stubbed={devin.status === "stubbed"}
          running={devin.status === "launching"}
          onReplay={() => void startNewSession()}
          showOpenCandidates={!candidatesOpen}
          onOpenCandidates={() => setCandidatesOpen(true)}
        />
        <Conversation className="min-h-0">
          <ConversationContent
            className="mx-auto w-full max-w-[50vw] gap-4 px-4 py-4"
            scrollClassName="chat-scrollbar overflow-x-hidden overflow-y-auto"
          >
            <SessionBanner
              status={devin.status}
              error={devin.error}
              sessionUrl={devin.session?.session_url ?? null}
            />
            <PlanChecklist
              plan={devin.checklist}
              launching={devin.status === "launching"}
            />
          </ConversationContent>
          <ConversationScrollButton />
        </Conversation>
      </div>
    </CockpitShell>
  )
}

function SessionBanner({
  status,
  error,
  sessionUrl,
}: {
  status: string
  error: string | null
  sessionUrl: string | null
}) {
  if (status === "idle" || status === "launching") return null
  if (status === "error") {
    return (
      <p className="text-sm text-destructive" role="alert">
        {error ?? "The API did not start a Devin session."}
      </p>
    )
  }
  if (status === "stubbed") {
    return (
      <p className="text-sm text-amber-600">
        Case is open, but Devin was stubbed. Set{" "}
        <code>DEVIN_API_KEY</code> on the API and start a new session.
        {error ? ` ${error}` : ""}
      </p>
    )
  }
  return (
    <p className="text-sm text-muted-foreground">
      Devin session is live
      {sessionUrl ? (
        <>
          {" · "}
          <a
            href={sessionUrl}
            target="_blank"
            rel="noreferrer"
            className="underline underline-offset-4"
          >
            open session
          </a>
        </>
      ) : null}
    </p>
  )
}
"use client"

import { useCallback, useEffect, useRef, useState } from "react"

import {
  alreadyLiveDialed,
  fetchCase,
  fetchEvents,
  openCase,
  placeLiveCall,
  sessionFromEvents,
} from "@/lib/live/api"
import {
  outreachIsLive,
  pickLiveCallSupplier,
  resolveChecklist,
} from "@/lib/live/checklist"
import { EVENT_POLL_MS, HOLD_FOR, PART_ID } from "@/lib/live/config"
import { fetchPlan, type LivePlan } from "@/lib/live/plan"
import type {
  CaseEvent,
  CaseSnapshot,
  LiveCandidate,
  OpenedCase,
  SessionInfo,
} from "@/lib/live/types"

export type DevinCaseStatus =
  | "idle"
  | "launching"
  | "live"
  | "stubbed"
  | "error"

type DevinCaseState = {
  status: DevinCaseStatus
  error: string | null
  caseId: string | null
  snapshot: CaseSnapshot | null
  events: CaseEvent[]
  plan: LivePlan | null
  session: SessionInfo | null
}

const EMPTY: DevinCaseState = {
  status: "idle",
  error: null,
  caseId: null,
  snapshot: null,
  events: [],
  plan: null,
  session: null,
}

function statusFromSession(session: SessionInfo | null): DevinCaseStatus {
  if (!session) return "live"
  return session.stubbed ? "stubbed" : "live"
}

export function useDevinCase(caseIdFromUrl: string | null) {
  const [state, setState] = useState<DevinCaseState>(EMPTY)

  const attach = useCallback(async (caseId: string, opened?: OpenedCase) => {
    const [snapshot, events, plan] = await Promise.all([
      fetchCase(caseId),
      fetchEvents(caseId),
      fetchPlan(caseId),
    ])
    const session =
      opened !== undefined
        ? {
            session_id: opened.session_id,
            session_url: opened.session_url,
            stubbed: opened.stubbed,
            error: opened.session_error,
          }
        : sessionFromEvents(events)
    setState({
      status: statusFromSession(session),
      error: session?.error ?? null,
      caseId,
      snapshot,
      events,
      plan,
      session,
    })
  }, [])

  const launch = useCallback(async () => {
    setState({ ...EMPTY, status: "launching" })
    try {
      const opened = await openCase(PART_ID)
      await attach(opened.case_id, opened)
      return opened.case_id
    } catch (cause) {
      const message =
        cause instanceof Error ? cause.message : "Could not open a case"
      setState({ ...EMPTY, status: "error", error: message })
      return null
    }
  }, [attach])

  useEffect(() => {
    if (!caseIdFromUrl) return
    let cancelled = false

    const load = async () => {
      try {
        await attach(caseIdFromUrl)
      } catch (cause) {
        if (cancelled) return
        const message =
          cause instanceof Error ? cause.message : "Could not load the case"
        setState({ ...EMPTY, status: "error", error: message })
      }
    }

    void load()
    return () => {
      cancelled = true
    }
  }, [attach, caseIdFromUrl])

  const eventsRef = useRef<CaseEvent[]>([])
  eventsRef.current = state.events

  useEffect(() => {
    const caseId = state.caseId
    if (!caseId || state.status === "error" || state.status === "launching") {
      return
    }
    let cancelled = false

    const tick = async () => {
      try {
        const since = eventsRef.current.at(-1)?.seq ?? 0
        const [snapshot, fresh, plan] = await Promise.all([
          fetchCase(caseId),
          fetchEvents(caseId, since),
          fetchPlan(caseId),
        ])
        if (cancelled) return
        setState((current) => {
          if (current.caseId !== caseId) return current
          const events =
            fresh.length > 0 ? [...current.events, ...fresh] : current.events
          const session = sessionFromEvents(events) ?? current.session
          return {
            ...current,
            snapshot,
            events,
            plan,
            session,
            status: statusFromSession(session),
            error: session?.error ?? current.error,
          }
        })
      } catch {
        // Keep the last good feed. The next tick retries.
      }
    }

    const interval = window.setInterval(() => void tick(), EVENT_POLL_MS)
    return () => {
      cancelled = true
      window.clearInterval(interval)
    }
  }, [state.caseId, state.status])

  const candidates: readonly LiveCandidate[] = state.snapshot?.candidates ?? []
  const checklist = state.plan
    ? resolveChecklist(state.plan, candidates)
    : null

  useEffect(() => {
    const caseId = state.caseId
    if (!caseId || !checklist) return
    if (!outreachIsLive(checklist)) return
    if (alreadyLiveDialed(state.events)) return
    const supplierRef = pickLiveCallSupplier(checklist, candidates, HOLD_FOR)
    if (!supplierRef) return
    void placeLiveCall(caseId, supplierRef).catch((cause) => {
      const message =
        cause instanceof Error ? cause.message : "Live call failed"
      setState((current) =>
        current.caseId === caseId
          ? { ...current, error: message }
          : current
      )
    })
  }, [candidates, checklist, state.caseId, state.events])

  return {
    ...state,
    candidates,
    checklist,
    launch,
    running: state.status === "launching" || state.status === "live",
  }
}
import { useCallback, useEffect, useState } from "react"

import {
  createCallingAgentPlan,
  getStepResponse,
  INITIAL_CALLING_AGENT_PLAN,
  latestCallingAgentEnd,
  resolveCallingAgentRuns,
  SCRIPT,
  STEP_SETTLE_DELAY_MS,
  STREAM_CHARS_PER_TICK,
  STREAM_TICK_MS,
} from "@/lib/case-001"

type PlaybackPhase = "waiting" | "text"
type PlaybackStatus = "streaming" | "stopped" | "complete"
type RehearsalTurnPhase = "pending" | "streaming" | "stopped" | "complete"

type PlaybackState = {
  status: PlaybackStatus
  phase: PlaybackPhase
  stepIndex: number
  text: string
}

const INITIAL_STATE: PlaybackState = {
  status: "streaming",
  phase: "waiting",
  stepIndex: 0,
  text: "",
}

// This hook is the timer-driven replacement seam for a live Devin Session.
// Keep its contract small so the Cockpit can later consume server events instead.
export function useDeterministicRehearsal(enabled = true) {
  const [playback, setPlayback] = useState<PlaybackState>(
    enabled ? INITIAL_STATE : { ...INITIAL_STATE, status: "stopped" }
  )
  const [agentPlan, setAgentPlan] = useState(INITIAL_CALLING_AGENT_PLAN)
  const [agentStartedAt, setAgentStartedAt] = useState<Record<string, number>>(
    {}
  )
  const [clock, setClock] = useState(0)

  useEffect(() => {
    if (!enabled) return
    const timeout = window.setTimeout(() => {
      setAgentPlan(createCallingAgentPlan())
    }, 0)

    return () => window.clearTimeout(timeout)
  }, [enabled])

  useEffect(() => {
    const step = SCRIPT[playback.stepIndex]
    if (
      playback.status !== "streaming" ||
      step?.kind !== "outreach" ||
      !step.callId ||
      agentStartedAt[step.callId] !== undefined
    ) {
      return
    }

    const callId = step.callId
    const timeout = window.setTimeout(() => {
      const startedAt = Date.now()
      setAgentStartedAt((current) => ({
        ...current,
        [callId]: startedAt,
      }))
      setClock(startedAt)
    }, 0)

    return () => window.clearTimeout(timeout)
  }, [agentStartedAt, playback.status, playback.stepIndex])

  useEffect(() => {
    if (
      playback.status !== "streaming" ||
      Object.keys(agentStartedAt).length === 0
    ) {
      return
    }

    const endAt = latestCallingAgentEnd(agentPlan, agentStartedAt)
    const updateClock = () => {
      const now = Date.now()
      setClock(now)
      return now >= endAt
    }

    if (updateClock()) return
    const interval = window.setInterval(() => {
      if (updateClock()) window.clearInterval(interval)
    }, 250)

    return () => window.clearInterval(interval)
  }, [agentPlan, agentStartedAt, playback.status])

  useEffect(() => {
    if (playback.status !== "streaming") return

    const step = SCRIPT[playback.stepIndex]
    if (!step) return

    if (playback.phase === "waiting") {
      const waitMs =
        step.id === "claims" &&
        agentPlan.every((agent) => agentStartedAt[agent.callId] !== undefined)
          ? Math.max(
              0,
              latestCallingAgentEnd(agentPlan, agentStartedAt) - Date.now()
            )
          : step.waitMs
      const timeout = window.setTimeout(() => {
        setPlayback((current) => {
          if (
            current.status !== "streaming" ||
            current.phase !== "waiting" ||
            current.stepIndex !== playback.stepIndex
          ) {
            return current
          }

          return { ...current, phase: "text", text: "" }
        })
      }, waitMs)

      return () => window.clearTimeout(timeout)
    }

    const response = getStepResponse(step)
    if (playback.text.length < response.length) {
      const timeout = window.setTimeout(() => {
        setPlayback((current) => {
          if (
            current.status !== "streaming" ||
            current.phase !== "text" ||
            current.stepIndex !== playback.stepIndex
          ) {
            return current
          }

          const nextLength = Math.min(
            current.text.length + STREAM_CHARS_PER_TICK,
            response.length
          )
          return { ...current, text: response.slice(0, nextLength) }
        })
      }, STREAM_TICK_MS)

      return () => window.clearTimeout(timeout)
    }

    const timeout = window.setTimeout(() => {
      setPlayback((current) => {
        if (
          current.status !== "streaming" ||
          current.phase !== "text" ||
          current.stepIndex !== playback.stepIndex
        ) {
          return current
        }

        const nextStepIndex = current.stepIndex + 1
        if (nextStepIndex === SCRIPT.length) {
          return {
            status: "complete",
            phase: "waiting",
            stepIndex: nextStepIndex,
            text: "",
          }
        }

        return {
          status: "streaming",
          phase: "waiting",
          stepIndex: nextStepIndex,
          text: "",
        }
      })
    }, STEP_SETTLE_DELAY_MS)

    return () => window.clearTimeout(timeout)
  }, [agentPlan, agentStartedAt, playback])

  const stop = useCallback(() => {
    setPlayback((current) => {
      if (current.status !== "streaming") return current
      return { ...current, status: "stopped" }
    })
  }, [])

  const replay = useCallback(() => {
    setAgentPlan(createCallingAgentPlan())
    setAgentStartedAt({})
    setClock(0)
    setPlayback(INITIAL_STATE)
  }, [])

  const currentStepIndex =
    playback.status === "streaming" ||
    (playback.status === "stopped" && playback.phase === "text")
      ? playback.stepIndex
      : null
  const currentPhase: RehearsalTurnPhase | null =
    currentStepIndex === null
      ? null
      : playback.status === "stopped"
        ? "stopped"
        : playback.phase === "waiting"
          ? "pending"
          : playback.text === getStepResponse(SCRIPT[playback.stepIndex])
            ? "complete"
            : "streaming"
  const revealedSteps =
    playback.status === "complete"
      ? SCRIPT.length
      : playback.stepIndex + (playback.phase === "text" ? 1 : 0)

