        event.preventDefault()
        show(slides.length - 1)
      } else if (event.key.toLowerCase() === "o") {
        setOverview((value) => !value)
      } else if (event.key.toLowerCase() === "f") {
        void toggleFullscreen()
      } else if (event.key === "Escape" && overview) {
        setOverview(false)
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [next, overview, previous, show, slides.length])

  function handleTouchEnd(event: React.TouchEvent) {
    if (touchStart.current === null) return
    const distance = event.changedTouches[0].clientX - touchStart.current
    touchStart.current = null
    if (Math.abs(distance) < 50) return
    if (distance < 0) next()
    else previous()
  }

  return (
    <main
      className={styles.stage}
      onTouchStart={(event) => {
        touchStart.current = event.touches[0].clientX
      }}
      onTouchEnd={handleTouchEnd}
    >
      {overview ? (
        <div className={styles.overview} aria-label="Slide overview">
          {slides.map((slide, index) => (
            <button
              type="button"
              className={styles.thumbnail}
              key={slide.label}
              onClick={() => show(index)}
              aria-label={`Open slide ${index + 1}: ${slide.label}`}
            >
              <div>{slide.content}</div>
              <span className={styles.thumbnailLabel}>
                {index + 1}. {slide.label}
              </span>
            </button>
          ))}
        </div>
      ) : (
        <div className={styles.viewport} aria-live="polite">
          {slides[current].content}
        </div>
      )}

      <nav className={styles.controls} aria-label="Presentation controls">
        <button
          className={styles.controlButton}
          type="button"
          onClick={previous}
          disabled={current === 0}
          aria-label="Previous slide"
        >
          <ArrowLeft size={18} stroke={1.8} />
        </button>
        <span className={styles.counter} aria-label="Current slide">
          {current + 1} / {slides.length}
        </span>
        <button
          className={styles.controlButton}
          type="button"
          onClick={next}
          disabled={current === slides.length - 1}
          aria-label="Next slide"
        >
          <ArrowRight size={18} stroke={1.8} />
        </button>
        <button
          className={styles.controlButton}
          type="button"
          onClick={() => setOverview((value) => !value)}
          aria-label="Toggle slide overview"
        >
          <GridDots size={18} stroke={1.8} />
        </button>
        <button
          className={styles.controlButton}
          type="button"
          onClick={() => void toggleFullscreen()}
          aria-label="Toggle fullscreen"
        >
          <ArrowsMaximize size={18} stroke={1.8} />
        </button>
      </nav>
    </main>
  )
}

