async function toggleFullscreen() {
  if (!document.fullscreenElement) {
    await document.documentElement.requestFullscreen()
    return
  }
  await document.exitFullscreen()
}

.stage {
  --deck-ink: oklch(0.95 0.006 72);
  --deck-muted: oklch(0.7 0.012 72);
  --deck-line: oklch(0.29 0.012 72);
  --deck-orange: oklch(0.72 0.19 46);
  --deck-black: oklch(0.135 0.005 72);
  align-items: center;
  background: #000;
  color: var(--deck-ink);
  display: flex;
  justify-content: center;
  min-height: 100dvh;
  overflow: hidden;
  position: relative;
  user-select: none;
}

.viewport {
  aspect-ratio: 16 / 9;
  background: var(--deck-black);
