  background: var(--deck-orange);
  bottom: 0;
  content: "";
  height: 0.55cqh;
  left: 0;
  position: absolute;
  transform: scaleX(0.11);
  transform-origin: left;
  width: 100%;
}

.title {
  font-size: clamp(2rem, 5.3cqw, 5.3rem);
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.98;
  max-width: 14ch;
  text-wrap: balance;
}

.titleWide {
  max-width: 20ch;
}

.body {
  color: var(--deck-muted);
  font-size: clamp(1rem, 1.85cqw, 1.85rem);
  line-height: 1.35;
}

.problemGrid {
  display: grid;
  flex: 1;
  gap: 2.2cqw;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 8cqh;
}

.problemItem {
  border-top: 1px solid var(--deck-line);
  display: flex;
  flex-direction: column;
  gap: 2.2cqh;
  padding-top: 2.8cqh;
